"""Every sound the house makes, generated by code: no samples, no rights to clear."""

from __future__ import annotations

from functools import lru_cache

import numpy as np

from . import RATE


def _t(seconds: float) -> np.ndarray:
    return np.arange(int(RATE * seconds)) / RATE


def _env(n: int, attack: float = 0.005, decay: float = 0.4) -> np.ndarray:
    t = np.arange(n) / RATE
    a = np.clip(t / max(attack, 1e-4), 0, 1)
    return a * np.exp(-t / max(decay, 1e-4))


def _bell_tone(freq: float, seconds: float, decay: float) -> np.ndarray:
    t = _t(seconds)
    # a struck bar: fundamental plus inharmonic partials that fade faster
    tone = (np.sin(2 * np.pi * freq * t)
            + 0.45 * np.sin(2 * np.pi * freq * 2.76 * t) * np.exp(-t / (decay * 0.5))
            + 0.2 * np.sin(2 * np.pi * freq * 5.40 * t) * np.exp(-t / (decay * 0.25)))
    return tone * _env(len(t), 0.002, decay)


def _silence(seconds: float) -> np.ndarray:
    return np.zeros(int(RATE * seconds))


def _normalize(x: np.ndarray, peak: float = 0.8) -> np.ndarray:
    m = float(np.max(np.abs(x))) or 1.0
    return (x / m * peak).astype(np.float32)


@lru_cache(maxsize=None)
def sound(name: str) -> np.ndarray:
    """Float32 mono samples at RATE, peak 0.8."""
    if name == "bell":           # ding-dong of the doorbell
        ding = _bell_tone(659.25, 1.1, 0.55)
        dong = _bell_tone(523.25, 1.6, 0.8)
        gap = int(RATE * 0.45)
        out = np.zeros(gap + len(dong))
        out[: len(ding)] += ding
        out[gap:] += dong
        return _normalize(out)
    if name == "chime":
        return _normalize(_bell_tone(987.77, 0.6, 0.25))
    if name == "beep_start":     # listening
        t = _t(0.14)
        f = 700 + 500 * t / t[-1]
        return _normalize(np.sin(2 * np.pi * np.cumsum(f) / RATE) * _env(len(t), 0.005, 0.12), 0.5)
    if name == "beep_end":       # done listening
        t = _t(0.14)
        f = 1200 - 500 * t / t[-1]
        return _normalize(np.sin(2 * np.pi * np.cumsum(f) / RATE) * _env(len(t), 0.005, 0.12), 0.5)
    if name == "beep":
        t = _t(0.12)
        return _normalize(np.sin(2 * np.pi * 880 * t) * _env(len(t), 0.003, 0.08), 0.5)
    if name == "alarm":          # two-tone, three times, not piercing
        parts = []
        for _ in range(3):
            for f in (880, 660):
                t = _t(0.22)
                sq = np.sign(np.sin(2 * np.pi * f * t)) * 0.35 + np.sin(2 * np.pi * f * t) * 0.65
                parts.append(sq * _env(len(t), 0.01, 0.6))
        return _normalize(np.concatenate(parts), 0.7)
    if name == "notify":
        a = _bell_tone(783.99, 0.35, 0.2)
        b = _bell_tone(1046.5, 0.6, 0.3)
        return _normalize(np.concatenate([a[: int(RATE * 0.14)], b]))
    if name == "error":
        t = _t(0.3)
        return _normalize(np.sin(2 * np.pi * 220 * t) * _env(len(t), 0.005, 0.2), 0.5)
    return _normalize(_bell_tone(880, 0.3, 0.15))


NAMES = ("bell", "chime", "beep_start", "beep_end", "beep", "alarm", "notify", "error")
